window.products.push({"id":1155820,"name":"Bay Window 1\" Adjustable Double Curtain Rod Set","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41RYjZhQ1UL._AC_SL1005_.jpg","description":"1\" Bay Window Adjustable Double Curtain Rod Set. The 1\" Bay Window Adjustable Curtain Rod is a stylish solution to cover your bay window! These bay window rods are all metal so you know they will last. Each rod has two flex joints to fit perfectly around your bay window! In addition, this set includes an extra extendable rod that will easily hook on to your bay window rod so you can hang both sheer and classic curtains with ease. 4 metal mounting brackets with screws and instructions are included in every Bay Window Adjustable Curtain Rod! Materials: Metal Dimensions: 78\"L x 1\"W x 1\"H Weight: 5.8 lbs","images":["https://m.media-amazon.com/images/I/41RYjZhQ1UL._AC_SL1005_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bay Window","source_asin":"B010RA529G","category_path":"Home & Kitchen"},"sku":"BM-1155820","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B010RA529G","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B010RA529G","price_pending":true,"merchant_ready":false});
